  $j${"engine": {"path": "ask623/w4/write/revert_eng_623.json", "md5": "595af423", "note": "the engine before the ASK 623 PUT (0d55aab1, with ASK 607 in it), saved by write623.sh; not rehearsed"}, "database": "the same md5-gated replaces with the strings swapped for the five functions; the neon row set inactive; the judge order restored through a log row; not rehearsed", "source": "audit 41709; notes623.md; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1, N2 (W3's draft 2)", "wall_id": 11708, "md5_graded": "6727a6c3", "verdict_norm": "PASS", "source": "Wall 11708; fairjudge/w1/g612/grade_ask623_d2.md (commit ab5a16a5)"}, {"seat": "W1", "verdict": "PASS WITH N1 TO N3 (plan rev 0)", "wall_id": 11716, "md5_graded": "87989e36", "verdict_norm": "PASS", "source": "Wall 11716; fairjudge/w1/g623/grade_plan623_rev0.md (commit 021079ce)"}, {"seat": "W1", "verdict": "PASS WITH N1 (build rev 0)", "wall_id": 11737, "md5_graded": "e449c187", "verdict_norm": "PASS", "source": "Wall 11737; fairjudge/w1/g623/grade_build623_rev0.md (commit 157e0626); write623.sql was graded as 01b4aa75"}, {"seat": "W1", "verdict": "PASS WITH N1, N2 (manual pairs draft 2, ASK 607 and 623 together)", "wall_id": 11748, "md5_graded": "6721facf", "verdict_norm": "PASS", "source": "Wall 11748; fairjudge/w1/g623/grade_manual607_623_d2.md 38b3477b (commit 62c26741)"}, {"seat": "W1", "verdict": "PASS (manual pairs draft 3)", "wall_id": 11751, "md5_graded": "3ac16429", "verdict_norm": "PASS", "source": "Wall 11751"}]$j$::jsonb,
