  $j$[{"name": "C1: one paid check call per model, a stored round-1 defender body with the model swapped, no reasoning or effort field", "result": "Hydrogen (execution 42337): finish stop, 14,453 completion tokens, a complete answer of 12,605 characters. Neon (execution 42339): finish stop, 16,582 completion tokens, a complete answer of 15,707 characters; its direct reply was cut at 125 s and the execution's output was read under the operator's yes. 0.369 dollars together.", "source": "Wall 11734; chk/summary_hydrogen.json, summary_neon.json"}, {"name": "C2 (t623.cjs): 132 pairings on the target", "result": "128 seat three judges; 4 stop with the ASK 608 reason (chatgpt and sol62 against glm, both ways), unchanged; no seated judge, reserve or alternate of a debater's family (both-Anthropic aside) or running a debater's model; no enforcer of a debater's family. ALL PASS.", "source": "notes623.md; out_t623.txt; W1's own run byte-equal, Wall 11737"}, {"name": "C3: the 90 present pairings, live against target", "result": "under order v2, 90 of 90 byte-equal; under the new order 22 identical and 68 change only in the alternates tail; 0 judge, reserve or enforcer changes", "source": "notes623.md; Wall 11735"}, {"name": "C4 and C5", "result": "Neon against Hydrogen, both ways: judges sol62, spark, sol; no Google seat; enforcer luna. The 8 Google pairings against chatgpt or sol62: spark, qwen4max, sonnet; enforcer glm; no reserve and no alternate", "source": "notes623.md; Wall 11735"}, {"name": "C6 (dry623.sql, rolled back): the database script and the line-up", "result": "all seven blocks apply; dash_judge_lineup equals the engine's Resolve Seats line-up on 128 of 128 seated pairings", "source": "notes623.md; out_c6_623.txt; Wall 11737"}, {"name": "C7 (c7_623.sql, rolled back): the recorders", "result": "before the write the substitution recorder refuses neon; after it both recorders accept hydrogen and neon; a Google alternate is still refused when a Google seat debates",